I've added a window transform to rank the data by attendance and filtered it to keep only the top 15 stadiums, keeping the y-axis sorted so the highest attendance appears at the top.

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Horizontal bar chart of match attendance by stadium.",
  "data": {
    "url": "data.csv"
  },
  "transform": [
    {
      "window": [
        {
          "op": "rank",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "attendance",
          "order": "descending"
        }
      ]
    },
    {
      "filter": "datum.rank <= 15"
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "attendance",
      "type": "quantitative",
      "title": "Attendance"
    },
    "y": {
      "field": "stadium",
      "type": "nominal",
      "title": "Stadium",
      "sort": "-x"
    },
    "color": {
      "field": "league",
      "type": "nominal",
      "title": "League",
      "scale": {
        "scheme": "colorblind"
      }
    }
  }
}
```

